from html.parser import HTMLParser
import pathlib, collections
h=pathlib.Path('2026-10-20-wordcount-diff.html').read_text()
class P(HTMLParser):
    def __init__(self):
        super().__init__(); self.ids=collections.Counter(); self.stack=[]; self.err=[]
        self.void={'meta','br','hr','img','input','link','area','base','col','embed','source','track','wbr'}
    def handle_starttag(self,t,a):
        d=dict(a)
        if 'id' in d: self.ids[d['id']]+=1
        if t not in self.void: self.stack.append(t)
    def handle_endtag(self,t):
        if t in self.void: return
        if self.stack and self.stack[-1]==t: self.stack.pop()
        else: self.err.append((t, list(self.stack[-3:])))
p=P(); p.feed(h)
print("dup ids:", [k for k,v in p.ids.items() if v>1])
print("unbalanced:", p.err[:5], "left open:", p.stack)
print("size bytes:", len(h.encode()))
print("presentation state:", 'window.__PRESENTATION_STATE__ = { version: 1, values: {} };' in h)
print("fullwidth punctuation left:", sum(h.count(c) for c in "、。，；：！？（）【】"))
